245	+    public async Task<float> Moles(Gas gas, params Vector2i[] tiles)
246	+    {
247	+        var total = 0f;
248	+        await _t.Server.WaitPost(() =>
249	+        {
250	+            var atmos = _t.Server.System<AtmosphereSystem>();
251	+            foreach (var tile in tiles)
252	+                total += atmos.GetTileMixture((Grid, null, null), null, tile)?.GetMoles(gas) ?? 0f;
253	+        });
