257	+    /// <summary>
258	+    /// What the client draws for a keyed sprite layer of the door: whether the layer is shown, and whether it
259	+    /// actually has a sprite state to draw (a blank placeholder layer draws nothing).
260	+    /// </summary>
261	+    public async Task<(bool Shown, bool Drawable)> ClientLayer(Enum key)
262	+    {
263	+        var shown = false;
264	+        var drawable = false;
265	+        var clientUid = _t.ToClientUid(Door);
266	+
267	+        await _t.Client.WaitPost(() =>
268	+        {
269	+            var spriteSys = _t.Client.System<SpriteSystem>();
270	+            var sprite = _t.CEntMan.GetComponent<SpriteComponent>(clientUid);
271	+            if (!spriteSys.LayerMapTryGet((clientUid, sprite), key, out var index, false)
272	+                || !spriteSys.TryGetLayer((clientUid, sprite), index, out var layer, false))
273	+                return;
274	+
275	+            shown = layer.Visible;
276	+            drawable = layer.ActualRsi is { } rsi && rsi.TryGetState(layer.State, out _);
277	+        });
278	+
279	+        return (shown, drawable);
280	+    }
