[metadata] {"type": "text", "file": {"filePath": "/app/task/tests/test.patch", "content": "diff --git a/Content.IntegrationTests/Tests/Doors/FirelockAnimationTest.cs b/Content.IntegrationTests/Tests/Doors/FirelockAnimationTest.cs\nnew file mode 100644\nindex 00000000..f27a9d37\n--- /dev/null\n+++ b/Content.IntegrationTests/Tests/Doors/FirelockAnimationTest.cs\n@@ -0,0 +1,93 @@\n+#nullable enable\n+using System.Collections.Generic;\n+using Content.IntegrationTests.Fixtures;\n+using Content.IntegrationTests.Fixtures.Attributes;\n+using Content.Shared.Doors.Components;\n+using Content.Shared.Doors.Systems;\n+using Robust.Client.GameObjects;\n+using Robust.Shared.GameObjects;\n+\n+namespace Content.IntegrationTests.Tests.Doors;\n+\n+/// <summary>\n+/// How a firelock's door panel moves on the client while it shuts.\n+/// </summary>\n+[TestOf(typeof(FirelockComponent))]\n+public sealed class FirelockAnimationTest : GameTest\n+{\n+    public override PoolSettings PoolSettings => new() { Connected = true, Fresh = true };\n+\n+    [SidedDependency(Side.Server)] private SharedDoorSystem _sDoorSystem = null!;\n+\n+    [Test]\n+    [Description(\"While a firelock shuts, its door panel plays its closing frames through to the end instead of \" +\n+                 \"holding one frame and then jumping to the shut picture.\")]\n+    public async Task ClosingAnimation_PlaysThroughBeforeTheDoorShuts()\n+    {\n+        await Pair.CreateTestMap();\n+\n+        EntityUid serverUid = default;\n+        await Server.WaitPost(() => serverUid = SSpawnAtPosition(\"Firelock\", TestMap!.GridCoords));\n+        await RunUntilSynced();\n+\n+        await Server.WaitAssertion(() =>\n+            Assert.That(SEntMan.GetComponent<DoorComponent>(serverUid).State, Is.EqualTo(DoorState.Open)));\n+\n+        var clientUid = ToClientUid(serverUid);\n+        string? closingState = null;\n+        var frameCount = 0;\n+        await Client.WaitPost(() =>\n+        {\n+            var door = CEntMan.GetComponent<DoorComponent>(clientUid);\n+            closingState = door.ClosingSpriteState;\n+            var spriteSys = Client.System<SpriteSystem>();\n+            var sprite = CEntMan.GetComponent<SpriteComponent>(clientUid);\n+            Assert.That(spriteSys.TryGetLayer((clientUid, sprite), DoorVisualLayers.Base, out var layer, false));\n+            Assert.That(closingState, Is.Not.Null);\n+            Assert.That(layer!.ActualRsi!.TryGetState(closingState!, out var state));\n+            frameCount = state!.DelayCount;\n+        });\n+        Assert.That(frameCount, Is.GreaterThan(6), \"The closing sprite should be a multi-frame animation.\");\n+\n+        await Server.WaitPost(() => _sDoorSystem.StartClosing(serverUid));\n+\n+        // Watch the client's door panel, tick by tick, until the door is shut and settled.\n+        var framesSeen = new HashSet<int>();\n+        var lastFrame = -1;\n+        for (var i = 0; i < 60; i++)\n+        {\n+            await RunTicksSync(1);\n+\n+            var settled = false;\n+            await Client.WaitPost(() =>\n+            {\n+                var spriteSys = Client.System<SpriteSystem>();\n+                var sprite = CEntMan.GetComponent<SpriteComponent>(clientUid);\n+                if (!spriteSys.TryGetLayer((clientUid, sprite), DoorVisualLayers.Base, out var layer, false))\n+                    return;\n+\n+                if (layer.State.Name == closingState)\n+                {\n+                    framesSeen.Add(layer.AnimationFrame);\n+                    lastFrame = Math.Max(lastFrame, layer.AnimationFrame);\n+                }\n+                else if (CEntMan.GetComponent<DoorComponent>(clientUid).State == DoorState.Closed && framesSeen.Count > 0)\n+                {\n+                    settled = true;\n+                }\n+            });\n+\n+            if (settled)\n+                break;\n+        }\n+\n+        Assert.Multiple(() =>\n+        {\n+            Assert.That(framesSeen, Is.Not.Empty, \"The closing animation never played.\");\n+            Assert.That(framesSeen.Count, Is.GreaterThanOrEqualTo(6),\n+                $\"The door panel showed only {framesSeen.Count} of its {frameCount} closing frames.\");\n+            Assert.That(lastFrame, Is.GreaterThanOrEqualTo(frameCount - 3),\n+                $\"The door panel never got near the end of its closing animation (last frame {lastFrame} of {frameCount}).\");\n+        });\n+    }\n+}\ndiff --git a/Content.IntegrationTests/Tests/Doors/FirelockLane.cs b/Content.IntegrationTests/Tests/Doors/FirelockLane.cs\nnew file mode 100644\nindex 00000000..330a024b\n--- /dev/null\n+++ b/Content.IntegrationTests/Tests/Doors/FirelockLane.cs\n@@ -0,0 +1,182 @@\n+#nullable enable\n+using System.Collections.Generic;\n+using Content.IntegrationTests.Fixtures;\n+using Content.Server.Atmos.EntitySystems;\n+using Content.Shared.Atmos;\n+using Content.Shared.Atmos.Components;\n+using Content.Shared.Doors.Components;\n+using Content.Shared.Doors.Systems;\n+using Content.Shared.Maps;\n+using Robust.Client.GameObjects;\n+using Robust.Shared.GameObjects;\n+using Robust.Shared.Map;\n+using Robust.Shared.Map.Components;\n+using Robust.Shared.Maths;\n+\n+namespace Content.IntegrationTests.Tests.Doors;\n+\n+/// <summary>\n+/// A small walled test bench for doors: a one-tile-wide lane on its own grid, with a lower cell (y = 0..1),\n+/// the door tile (y = 2) and an upper cell (y = 3..4). The upper cell can instead be left open to space.\n+/// Everything here goes through public game systems only: spawn, open/close, read and change tile air, and\n+/// read what the client draws.\n+/// </summary>\n+internal sealed class FirelockLane\n+{\n+    public static readonly Vector2i DoorTile = new(0, 2);\n+    public static readonly Vector2i[] Lower = { new(0, 0), new(0, 1) };\n+    public static readonly Vector2i[] Upper = { new(0, 3), new(0, 4) };\n+\n+    public EntityUid Grid;\n+    public EntityUid Door;\n+\n+    private readonly GameTest _t;\n+\n+    private FirelockLane(GameTest t)\n+    {\n+        _t = t;\n+    }\n+\n+    public static async Task<FirelockLane> Build(GameTest t, string doorProto, bool upperIsSpace = false)\n+    {\n+        var lane = new FirelockLane(t);\n+\n+        await t.Server.WaitPost(() =>\n+        {\n+            var mapSys = t.Server.System<SharedMapSystem>();\n+            var tileDefs = t.Server.ResolveDependency<ITileDefinitionManager>();\n+            var floor = tileDefs[\"FloorSteel\"].TileId;\n+            var plating = tileDefs[\"Plating\"].TileId;\n+\n+            mapSys.CreateMap(out var mapId);\n+            var grid = mapSys.CreateGridEntity(mapId);\n+            lane.Grid = grid.Owner;\n+\n+            var walls = new List<Vector2i>();\n+            for (var x = -1; x <= 1; x++)\n+            {\n+                for (var y = -1; y <= 5; y++)\n+                {\n+                    // Open to space: no floor above the door, and no wall closing it off at the top.\n+                    if (upperIsSpace && x == 0 && y >= 3)\n+                        continue;\n+\n+                    var isWall = x != 0 || y == -1 || y == 5;\n+                    mapSys.SetTile(grid.Owner, grid.Comp, new Vector2i(x, y), new Tile(isWall ? plating : floor));\n+                    if (isWall)\n+                        walls.Add(new Vector2i(x, y));\n+                }\n+            }\n+\n+            t.SEntMan.EnsureComponent<GridAtmosphereComponent>(grid.Owner);\n+            t.SEntMan.EnsureComponent<GasTileOverlayComponent>(grid.Owner);\n+\n+            foreach (var w in walls)\n+                t.SEntMan.SpawnEntity(\"WallSolid\", new EntityCoordinates(grid.Owner, w.X + 0.5f, w.Y + 0.5f));\n+\n+            lane.Door = t.SEntMan.SpawnEntity(doorProto, new EntityCoordinates(grid.Owner, DoorTile.X + 0.5f, DoorTile.Y + 0.5f));\n+        });\n+\n+        await t.RunTicksSync(5);\n+        return lane;\n+    }\n+\n+    public DoorState ServerState => _t.SEntMan.GetComponent<DoorComponent>(Door).State;\n+\n+    public async Task WaitForState(DoorState state)\n+    {\n+        await PoolManager.WaitUntil(_t.Server, () => ServerState == state);\n+        Assert.That(ServerState, Is.EqualTo(state));\n+    }\n+\n+    /// <summary>\n+    /// Shuts the door and waits until it is fully closed.\n+    /// </summary>\n+    /// <param name=\"asIfMappedShut\">\n+    /// Also have atmos re-read the door tile once, the way a door that was already shut when the map loaded is\n+    /// seen. Tests that are not about how a door seals use this, so they only depend on what they check.\n+    /// </param>\n+    public async Task Close(bool asIfMappedShut)\n+    {\n+        var doors = _t.Server.System<SharedDoorSystem>();\n+        await _t.Server.WaitPost(() => doors.TryClose(Door));\n+        await WaitForState(DoorState.Closed);\n+\n+        if (asIfMappedShut)\n+            await _t.Server.WaitPost(() => _t.Server.System<AtmosphereSystem>().InvalidateTile(Grid, DoorTile));\n+\n+        await _t.RunTicksSync(5);\n+    }\n+\n+    /// <summary>\n+    /// Gives every tile on the lane the normal round-start air.\n+    /// </summary>\n+    public async Task FillAir()\n+    {\n+        await _t.Server.WaitPost(() =>\n+        {\n+            var atmos = _t.Server.System<AtmosphereSystem>();\n+            atmos.RebuildGridAtmosphere((Grid,\n+                _t.SEntMan.GetComponent<GridAtmosphereComponent>(Grid),\n+                _t.SEntMan.GetComponent<MapGridComponent>(Grid)));\n+        });\n+        await _t.RunTicksSync(2);\n+    }\n+\n+    public async Task ChangeAir(IEnumerable<Vector2i> tiles, Action<GasMixture> change)\n+    {\n+        await _t.Server.WaitPost(() =>\n+        {\n+            var atmos = _t.Server.System<AtmosphereSystem>();\n+            foreach (var tile in tiles)\n+            {\n+                var mix = atmos.GetTileMixture((Grid, null, null), null, tile, excite: true);\n+                Assert.That(mix, Is.Not.Null, $\"Tile {tile} has no air to change.\");\n+                change(mix!);\n+            }\n+        });\n+    }\n+\n+    public async Task<float> Moles(Gas gas, params Vector2i[] tiles)\n+    {\n+        var total = 0f;\n+        await _t.Server.WaitPost(() =>\n+        {\n+            var atmos = _t.Server.System<AtmosphereSystem>();\n+            foreach (var tile in tiles)\n+                total += atmos.GetTileMixture((Grid, null, null), null, tile)?.GetMoles(gas) ?? 0f;\n+        });\n+        return total;\n+    }\n+\n+    /// <summary>\n+    /// What the client draws for a keyed sprite layer of the door: whether the layer is shown, and whether it\n+    /// actually has a sprite state to draw (a blank placeholder layer draws nothing).\n+    /// </summary>\n+    public async Task<(bool Shown, bool Drawable)> ClientLayer(Enum key)\n+    {\n+        var shown = false;\n+        var drawable = false;\n+        var clientUid = _t.ToClientUid(Door);\n+\n+        await _t.Client.WaitPost(() =>\n+        {\n+            var spriteSys = _t.Client.System<SpriteSystem>();\n+            var sprite = _t.CEntMan.GetComponent<SpriteComponent>(clientUid);\n+            if (!spriteSys.LayerMapTryGet((clientUid, sprite), key, out var index, false)\n+                || !spriteSys.TryGetLayer((clientUid, sprite), index, out var layer, false))\n+                return;\n+\n+            shown = layer.Visible;\n+            drawable = layer.ActualRsi is { } rsi && rsi.TryGetState(layer.State, out _);\n+        });\n+\n+        return (shown, drawable);\n+    }\n+\n+    public async Task<bool> WarningShown(Enum key)\n+    {\n+        var (shown, drawable) = await ClientLayer(key);\n+        return shown && drawable;\n+    }\n+}\ndiff --git a/Content.IntegrationTests/Tests/Doors/FirelockSealTest.cs b/Content.IntegrationTests/Tests/Doors/FirelockSealTest.cs\nnew file mode 100644\nindex 00000000..b961ddb8\n--- /dev/null\n+++ b/Content.IntegrationTests/Tests/Doors/FirelockSealTest.cs\n@@ -0,0 +1,75 @@\n+#nullable enable\n+using Content.IntegrationTests.Fixtures;\n+using Content.Shared.Atmos;\n+using Content.Shared.Doors.Components;\n+using Robust.Shared.GameObjects;\n+\n+namespace Content.IntegrationTests.Tests.Doors;\n+\n+/// <summary>\n+/// What a shut firelock keeps out. Gas is released on one side of the door and the other side is checked\n+/// after the air has had time to spread.\n+/// </summary>\n+[TestOf(typeof(FirelockComponent))]\n+public sealed class FirelockSealTest : GameTest\n+{\n+    public override PoolSettings PoolSettings => new() { Connected = true, Fresh = true };\n+\n+    private const float Released = 200f;\n+\n+    // Far below anything that could have flowed through an open gap in four seconds.\n+    private const float Trace = 1f;\n+\n+    [Test]\n+    [Description(\"A firelock that was shut while the round was running holds back gas released behind it afterwards.\")]\n+    public async Task ClosedFirelock_HoldsBackGasReleasedAfterClosing()\n+    {\n+        var lane = await FirelockLane.Build(this, \"Firelock\");\n+        await lane.FillAir();\n+\n+        // Filling the lane makes atmos re-read every tile on its next pass. Let that settle while the door is\n+        // still open, so that afterwards only the door shutting can seal its tile.\n+        await RunSeconds(2);\n+\n+        // Shut it during play, then release gas on one side.\n+        await lane.Close(asIfMappedShut: false);\n+        await lane.ChangeAir(FirelockLane.Upper, m => m.AdjustMoles(Gas.Plasma, Released));\n+        await RunSeconds(4);\n+\n+        var behind = await lane.Moles(Gas.Plasma, FirelockLane.Upper);\n+        var through = await lane.Moles(Gas.Plasma, FirelockLane.Lower);\n+        Assert.Multiple(() =>\n+        {\n+            Assert.That(behind, Is.GreaterThan(Released), \"The released gas should still be behind the firelock.\");\n+            Assert.That(through, Is.LessThan(Trace),\n+                $\"{through:F1} mol of the gas got past a shut firelock.\");\n+        });\n+    }\n+\n+    [Test]\n+    [Description(\"An edge firelock seals along the edge its door panel is drawn on (the bottom edge of its tile when \" +\n+                 \"unrotated): gas on that side stays on that side and never reaches the firelock's own tile.\")]\n+    public async Task EdgeFirelock_SealsAlongItsDoorEdge()\n+    {\n+        // Unrotated, the edge firelock's door panel is drawn along the bottom (south) edge of its tile, so the\n+        // lane's lower cell is beyond the panel and the firelock's own tile and the upper cell are on its near side.\n+        var lane = await FirelockLane.Build(this, \"FirelockEdge\");\n+        await lane.Close(asIfMappedShut: true);\n+        await lane.FillAir();\n+\n+        await lane.ChangeAir(FirelockLane.Lower, m => m.AdjustMoles(Gas.Plasma, Released));\n+        await RunSeconds(4);\n+\n+        var held = await lane.Moles(Gas.Plasma, FirelockLane.Lower);\n+        var onDoorTile = await lane.Moles(Gas.Plasma, FirelockLane.DoorTile);\n+        var past = await lane.Moles(Gas.Plasma, FirelockLane.Upper);\n+        Assert.Multiple(() =>\n+        {\n+            Assert.That(held, Is.GreaterThan(Released), \"The released gas should still be below the door panel.\");\n+            Assert.That(onDoorTile, Is.LessThan(Trace),\n+                $\"{onDoorTile:F1} mol of gas reached the edge firelock's own tile from beyond its door panel.\");\n+            Assert.That(past, Is.LessThan(Trace),\n+                $\"{past:F1} mol of gas got past the edge firelock.\");\n+        });\n+    }\n+}\ndiff --git a/Content.IntegrationTests/Tests/Doors/FirelockWarningLightTest.cs b/Content.IntegrationTests/Tests/Doors/FirelockWarningLightTest.cs\nnew file mode 100644\nindex 00000000..1f96ced4\n--- /dev/null\n+++ b/Content.IntegrationTests/Tests/Doors/FirelockWarningLightTest.cs\n@@ -0,0 +1,169 @@\n+#nullable enable\n+using Content.IntegrationTests.Fixtures;\n+using Content.IntegrationTests.Fixtures.Attributes;\n+using Content.Shared.Atmos;\n+using Content.Shared.Doors.Components;\n+using Content.Shared.Doors.Systems;\n+using Content.Shared.Tools.Systems;\n+using Robust.Shared.GameObjects;\n+\n+namespace Content.IntegrationTests.Tests.Doors;\n+\n+/// <summary>\n+/// The warning lights a firelock shows while it is shut and holding something back. Each test builds a real\n+/// hazard next to the door and checks what the client draws.\n+/// </summary>\n+[TestOf(typeof(FirelockComponent))]\n+public sealed class FirelockWarningLightTest : GameTest\n+{\n+    // A brand-new server/client pair per test, so a failure is always reported under the test that caused it.\n+    public override PoolSettings PoolSettings => new() { Connected = true, Fresh = true };\n+\n+    [SidedDependency(Side.Server)] private SharedDoorSystem _sDoorSystem = null!;\n+    [SidedDependency(Side.Server)] private WeldableSystem _sWeldable = null!;\n+\n+    /// <summary>\n+    /// A lane whose upper cell holds far more air than the lower one, at the same temperature.\n+    /// </summary>\n+    private async Task<FirelockLane> OverPressureLane(string proto)\n+    {\n+        var lane = await FirelockLane.Build(this, proto);\n+        await lane.Close(asIfMappedShut: true);\n+        await lane.FillAir();\n+        await lane.ChangeAir(FirelockLane.Upper, m => m.AdjustMoles(Gas.Nitrogen, 200f));\n+        await RunSeconds(3);\n+        await RunUntilSynced();\n+        return lane;\n+    }\n+\n+    /// <summary>\n+    /// A lane whose upper cell holds searing hot air: hot enough for the temperature warning, and the heat also\n+    /// pushes its pressure up far enough for the pressure warning.\n+    /// </summary>\n+    private async Task<FirelockLane> HotLane(string proto)\n+    {\n+        var lane = await FirelockLane.Build(this, proto);\n+        await lane.Close(asIfMappedShut: true);\n+        await lane.FillAir();\n+        await lane.ChangeAir(FirelockLane.Upper, m => m.Temperature = 1000f);\n+        await RunSeconds(3);\n+        await RunUntilSynced();\n+        return lane;\n+    }\n+\n+    private async Task AssertNoWarningShown(FirelockLane lane, string when)\n+    {\n+        var pressure = await lane.WarningShown(FirelockVisualLayersPressure.Base);\n+        var temperature = await lane.WarningShown(FirelockVisualLayersTemperature.Base);\n+        Assert.Multiple(() =>\n+        {\n+            Assert.That(pressure, Is.False, $\"The pressure warning shows on a firelock that is {when}.\");\n+            Assert.That(temperature, Is.False, $\"The temperature warning shows on a firelock that is {when}.\");\n+        });\n+    }\n+\n+    private async Task AssertBothWarningsShown(FirelockLane lane, string when)\n+    {\n+        var pressure = await lane.WarningShown(FirelockVisualLayersPressure.Base);\n+        var temperature = await lane.WarningShown(FirelockVisualLayersTemperature.Base);\n+        Assert.Multiple(() =>\n+        {\n+            Assert.That(pressure, $\"A firelock that is {when} and holding back hot, high-pressure air should show its pressure warning.\");\n+            Assert.That(temperature, $\"A firelock that is {when} and holding back hot, high-pressure air should show its temperature warning.\");\n+        });\n+    }\n+\n+    [Test]\n+    [Description(\"Once a firelock leaves its shut state (opening, open, closing again) neither of its warning lights \" +\n+                 \"shows, even though whatever it was holding back has not gone away.\")]\n+    public async Task WarningLights_HideWhenDoorLeavesClosed()\n+    {\n+        var lane = await HotLane(\"Firelock\");\n+        await AssertBothWarningsShown(lane, \"shut\");\n+\n+        // Opening: sampled while the door is still moving.\n+        await Server.WaitPost(() => _sDoorSystem.StartOpening(lane.Door));\n+        await RunTicksSync(3);\n+        await RunUntilSynced();\n+        Assert.That(lane.ServerState, Is.EqualTo(DoorState.Opening), \"Precondition: the door should still be opening.\");\n+        await AssertNoWarningShown(lane, \"opening\");\n+\n+        // Fully open.\n+        await lane.WaitForState(DoorState.Open);\n+        await RunUntilSynced();\n+        await AssertNoWarningShown(lane, \"open\");\n+\n+        // Shutting again: sampled while the door is still moving.\n+        await Server.WaitPost(() => _sDoorSystem.StartClosing(lane.Door));\n+        await RunTicksSync(6);\n+        await RunUntilSynced();\n+        Assert.That(lane.ServerState, Is.EqualTo(DoorState.Closing), \"Precondition: the door should still be closing.\");\n+        await AssertNoWarningShown(lane, \"closing\");\n+    }\n+\n+    [Test]\n+    [Description(\"A glass firelock that is shut and holding back high pressure shows the same pressure warning a \" +\n+                 \"standard firelock shows.\")]\n+    public async Task WarningLights_GlassFirelockShowsWarning()\n+    {\n+        var lane = await OverPressureLane(\"FirelockGlass\");\n+\n+        Assert.That(await lane.WarningShown(FirelockVisualLayersPressure.Base),\n+            \"A shut glass firelock holding back high pressure shows no pressure warning.\");\n+    }\n+\n+    [Test]\n+    [Description(\"A shut firelock with open space on one side and normal air on the other is holding back pressure: \" +\n+                 \"it shows the pressure warning and not the temperature one.\")]\n+    public async Task WarningLights_SpaceBreachIsAPressureWarning()\n+    {\n+        var lane = await FirelockLane.Build(this, \"Firelock\", upperIsSpace: true);\n+        await lane.Close(asIfMappedShut: true);\n+        await lane.FillAir();\n+        await RunSeconds(3);\n+        await RunUntilSynced();\n+\n+        var breachPressure = await lane.WarningShown(FirelockVisualLayersPressure.Base);\n+        var breachTemperature = await lane.WarningShown(FirelockVisualLayersTemperature.Base);\n+        Assert.Multiple(() =>\n+        {\n+            Assert.That(breachPressure, \"A firelock sealing a room off from space should show its pressure warning.\");\n+            Assert.That(breachTemperature, Is.False,\n+                \"A firelock sealing an ordinary room off from space shows the temperature warning.\");\n+        });\n+    }\n+\n+    [Test]\n+    [Description(\"Guard: each warning keeps reacting to its own kind of hazard.\")]\n+    public async Task WarningLights_MatchTheHazardKind()\n+    {\n+        // Same temperature on both sides, much more air on one: pressure only.\n+        var pressure = await OverPressureLane(\"Firelock\");\n+        var opPressure = await pressure.WarningShown(FirelockVisualLayersPressure.Base);\n+        var opTemperature = await pressure.WarningShown(FirelockVisualLayersTemperature.Base);\n+        Assert.Multiple(() =>\n+        {\n+            Assert.That(opPressure, \"Over-pressure should show the pressure warning.\");\n+            Assert.That(opTemperature, Is.False, \"Over-pressure at room temperature should not show the temperature warning.\");\n+        });\n+\n+        // Searing hot air on one side: the temperature warning shows.\n+        var hot = await HotLane(\"Firelock\");\n+        Assert.That(await hot.WarningShown(FirelockVisualLayersTemperature.Base),\n+            \"A firelock holding back searing hot air should show the temperature warning.\");\n+    }\n+\n+    [Test]\n+    [Description(\"Guard: a firelock welded shut is still shut, so it keeps showing its warnings.\")]\n+    public async Task WarningLights_StayOnWhileWelded()\n+    {\n+        var lane = await HotLane(\"Firelock\");\n+\n+        await Server.WaitPost(() => _sWeldable.SetWeldedState(lane.Door, true));\n+        await lane.WaitForState(DoorState.Welded);\n+        await RunSeconds(2);\n+        await RunUntilSynced();\n+\n+        await AssertBothWarningsShown(lane, \"welded shut\");\n+    }\n+}\n", "numLines": 544, "startLine": 1, "totalLines": 544}}

