221	+        await _t.Server.WaitPost(() =>
222	+        {
223	+            var atmos = _t.Server.System<AtmosphereSystem>();
224	+            atmos.RebuildGridAtmosphere((Grid,
225	+                _t.SEntMan.GetComponent<GridAtmosphereComponent>(Grid),
226	+                _t.SEntMan.GetComponent<MapGridComponent>(Grid)));
227	+        });
228	+        await _t.RunTicksSync(2);
229	+    }
230	+
231	+    public async Task ChangeAir(IEnumerable<Vector2i> tiles, Action<GasMixture> change)
232	+    {
233	+        await _t.Server.WaitPost(() =>
234	+        {
235	+            var atmos = _t.Server.System<AtmosphereSystem>();
236	+            foreach (var tile in tiles)
237	+            {
238	+                var mix = atmos.GetTileMixture((Grid, null, null), null, tile, excite: true);
239	+                Assert.That(mix, Is.Not.Null, $"Tile {tile} has no air to change.");
240	+                change(mix!);
241	+            }
242	+        });
243	+    }
