271	+            if (!spriteSys.LayerMapTryGet((clientUid, sprite), key, out var index, false)
272	+                || !spriteSys.TryGetLayer((clientUid, sprite), index, out var layer, false))
273	+                return;
274	+
275	+            shown = layer.Visible;
