303	+/// What a shut firelock keeps out. Gas is released on one side of the door and the other side is checked
304	+/// after the air has had time to spread.
305	+/// </summary>
306	+[TestOf(typeof(FirelockComponent))]
307	+public sealed class FirelockSealTest : GameTest
308	+{
309	+    public override PoolSettings PoolSettings => new() { Connected = true, Fresh = true };
310	+
311	+    private const float Released = 200f;
312	+
313	+    // Far below anything that could have flowed through an open gap in four seconds.
314	+    private const float Trace = 1f;
315	+
316	+    [Test]
317	+    [Description("A firelock that was shut while the round was running holds back gas released behind it afterwards.")]
318	+    public async Task ClosedFirelock_HoldsBackGasReleasedAfterClosing()
319	+    {
320	+        var lane = await FirelockLane.Build(this, "Firelock");
321	+        await lane.FillAir();
322	+
323	+        // Filling the lane makes atmos re-read every tile on its next pass. Let that settle while the door is
324	+        // still open, so that afterwards only the door shutting can seal its tile.
325	+        await RunSeconds(2);
326	+
327	+        // Shut it during play, then release gas on one side.
328	+        await lane.Close(asIfMappedShut: false);
329	+        await lane.ChangeAir(FirelockLane.Upper, m => m.AdjustMoles(Gas.Plasma, Released));
330	+        await RunSeconds(4);
331	+
332	+        var behind = await lane.Moles(Gas.Plasma, FirelockLane.Upper);
333	+        var through = await lane.Moles(Gas.Plasma, FirelockLane.Lower);
334	+        Assert.Multiple(() =>
335	+        {
336	+            Assert.That(behind, Is.GreaterThan(Released), "The released gas should still be behind the firelock.");
337	+            Assert.That(through, Is.LessThan(Trace),
338	+                $"{through:F1} mol of the gas got past a shut firelock.");
339	+        });
340	+    }
341	+
342	+    [Test]
343	+    [Description("An edge firelock seals along the edge its door panel is drawn on (the bottom edge of its tile when " +
344	+                 "unrotated): gas on that side stays on that side and never reaches the firelock's own tile.")]
345	+    public async Task EdgeFirelock_SealsAlongItsDoorEdge()
346	+    {
347	+        // Unrotated, the edge firelock's door panel is drawn along the bottom (south) edge of its tile, so the
348	+        // lane's lower cell is beyond the panel and the firelock's own tile and the upper cell are on its near side.
349	+        var lane = await FirelockLane.Build(this, "FirelockEdge");
350	+        await lane.Close(asIfMappedShut: true);
351	+        await lane.FillAir();
352	+
353	+        await lane.ChangeAir(FirelockLane.Lower, m => m.AdjustMoles(Gas.Plasma, Released));
354	+        await RunSeconds(4);
355	+
356	+        var held = await lane.Moles(Gas.Plasma, FirelockLane.Lower);
357	+        var onDoorTile = await lane.Moles(Gas.Plasma, FirelockLane.DoorTile);
358	+        var past = await lane.Moles(Gas.Plasma, FirelockLane.Upper);
359	+        Assert.Multiple(() =>
360	+        {
361	+            Assert.That(held, Is.GreaterThan(Released), "The released gas should still be below the door panel.");
362	+            Assert.That(onDoorTile, Is.LessThan(Trace),
363	+                $"{onDoorTile:F1} mol of gas reached the edge firelock's own tile from beyond its door panel.");
364	+            Assert.That(past, Is.LessThan(Trace),
365	+                $"{past:F1} mol of gas got past the edge firelock.");
366	+        });
367	+    }
